import { takaro, data, TakaroUserError } from '@takaro/helpers';

async function main() {
  const { gameServerId, pog: sender, module: mod } = data;

  // try to find a variable with key "confirmTransfer"
  const variables = (
    await takaro.variable.variableControllerSearch({
      filters: {
        key: ['confirmTransfer'],
        gameServerId: [gameServerId],
        moduleId: [mod.moduleId],
        playerId: [sender.playerId],
      },
    })
  ).data.data;

  if (variables.length === 0) {
    throw new TakaroUserError('You have no pending transfer.');
  }

  // Remove the variable before potentially executing the transaction.
  await takaro.variable.variableControllerDelete(variables[0].id);
  const pendingTransfer = JSON.parse(variables[0].value);

  await takaro.playerOnGameserver.playerOnGameServerControllerTransactBetweenPlayers(
    sender.gameServerId,
    sender.id,
    pendingTransfer.receiver.id,
    {
      currency: pendingTransfer.amount,
      reason: 'Player transfer',
    },
  );

  const receiverName = (await takaro.player.playerControllerGetOne(pendingTransfer.receiver.playerId)).data.data.name;
  const senderName = (await takaro.player.playerControllerGetOne(sender.playerId)).data.data.name;
  const currencyName = (await takaro.settings.settingsControllerGetOne('currencyName', gameServerId)).data.data.value;

  const messageToSender = sender.pm(
    `You successfully transferred ${pendingTransfer.amount} ${currencyName} to ${receiverName}`,
  );

  const messageToReceiver = takaro.gameserver.gameServerControllerSendMessage(gameServerId, {
    message: `You received ${pendingTransfer.amount} ${currencyName} from ${senderName}`,
    opts: {
      recipient: {
        gameId: pendingTransfer.receiver.gameId,
      },
    },
  });
  await Promise.all([messageToSender, messageToReceiver]);
}

await main();

import { takaro, data, TakaroUserError } from '@takaro/helpers';

async function main() {
  const { pog: sender, arguments: args, gameServerId, module: mod } = data;

  const currencyName = (await takaro.settings.settingsControllerGetOne('currencyName', gameServerId)).data.data.value;

  const prefix = (await takaro.settings.settingsControllerGetOne('commandPrefix', gameServerId)).data.data.value;

  // args.receiver has an argument type of "player". Arguments of this type are automatically resolved to the player's id.
  // If the player doesn't exist or multiple players with the same name where found, it will have thrown an error before this command is executed.
  const receiver = args.receiver;
  const senderName = (await takaro.player.playerControllerGetOne(sender.playerId)).data.data.name;
  const receiverName = (await takaro.player.playerControllerGetOne(receiver.playerId)).data.data.name;

  if (mod.userConfig.pendingAmount !== 0 && args.amount >= mod.userConfig.pendingAmount) {
    // create a variable to store confirmation requirement
    // TODO: in the future, we should probably add an expiration date to this variable.
    await takaro.variable.variableControllerCreate({
      key: 'confirmTransfer',
      value: JSON.stringify({
        amount: args.amount,
        receiver: {
          id: receiver.id,
          gameId: receiver.gameId,
          playerId: receiver.playerId,
        },
      }),
      moduleId: mod.moduleId,
      playerId: sender.playerId,
      gameServerId,
    });

    // NOTE: we should maybe check if the player has enough balance to send the amount since this is only checked when the transaction is executed.
    await sender.pm(
      `You are about to send ${args.amount} ${currencyName} to ${receiverName}. (Please confirm by typing ${prefix}confirmtransfer)`,
    );
    return;
  }

  try {
    await takaro.playerOnGameserver.playerOnGameServerControllerTransactBetweenPlayers(
      sender.gameServerId,
      sender.id,
      receiver.id,
      {
        currency: args.amount,
        reason: 'Player transfer',
      },
    );
  } catch {
    throw new TakaroUserError(
      `Failed to transfer ${args.amount} ${currencyName} to ${receiverName}. Are you sure you have enough balance?`,
    );
  }

  const messageToReceiver = takaro.gameserver.gameServerControllerSendMessage(gameServerId, {
    message: `You received ${args.amount} ${currencyName} from ${senderName}`,
    opts: {
      recipient: {
        gameId: receiver.gameId,
      },
    },
  });

  await Promise.all([
    sender.pm(`You successfully transferred ${args.amount} ${currencyName} to ${receiverName}`),
    messageToReceiver,
  ]);

}

await main();

import { takaro, data, TakaroUserError } from '@takaro/helpers';

async function searchOrders(filters) {
  const res = await takaro.shopOrder.shopOrderControllerSearch({
    filters,
    sortBy: 'createdAt',
    sortDirection: 'asc',
  });
  return res.data.data;
}

async function main() {
  const { user, player, arguments: args, gameServerId } = data;

  if (!user) {
    throw new TakaroUserError('You must link your account to Takaro to use this command.');
  }

  const scope = { userId: [user.id] };

  // Only filter by gameServerId if it's available (should always be present in command context)
  if (gameServerId) {
    scope.gameServerId = [gameServerId];
  }

  // Paid orders first, then claimed ones whose items definitively could not be handed over
  // (claiming one again retries the delivery), each oldest first. A failed delivery that keeps
  // failing must not stand in front of an order that was never claimed.
  const paid = await searchOrders({ ...scope, status: ['PAID'] });
  const failedDelivery = await searchOrders({ ...scope, status: ['COMPLETED'], deliveryStatus: ['FAILED'] });
  const pendingOrders = [...paid, ...failedDelivery];

  if (pendingOrders.length === 0) {
    await player.pm('You have no pending orders.');
    return;
  }

  let claimedAny = false;
  for (const order of pendingOrders) {
    let claimed;
    try {
      claimed = (await takaro.shopOrder.shopOrderControllerClaim(order.id)).data.data;
    } catch (error) {
      // A failed delivery can become unclaimable (its listing was removed or unpublished). It
      // must not block the orders behind it, so it is skipped; a paid order's refusal is not.
      if (order.status === 'PAID') {
        throw error;
      }
      continue;
    }
    claimedAny = true;
    if (claimed.deliveryStatus === 'FAILED') {
      await player.pm('The items of an order could not be handed over. Use /claim to try again.');
    } else if (claimed.deliveryStatus === 'UNKNOWN') {
      await player.pm('The delivery of an order could not be confirmed. Ask an admin to check it.');
    }
    if (!args.all) {
      break;
    }
  }

  if (!claimedAny) {
    await player.pm('None of your pending orders can be claimed right now. Ask an admin to check them.');
  }
}

await main();

import { takaro, data, TakaroUserError } from '@takaro/helpers';

// The six operator phrases of a listing's variable purchase restriction (GH #2522), restated here
// because a module cannot import from app-api. Only the PHRASING is copied: this command never
// evaluates the requirement, it only prints it - the refusal still comes from the server.
const REQUIREMENT_PHRASES = {
  gte: 'at least',
  gt: 'more than',
  lte: 'at most',
  lt: 'less than',
  eq: 'exactly',
  ne: 'not',
};

// oxlint-disable-next-line sonarjs/cognitive-complexity -- GH #4103
async function main() {
  const { arguments: args, player, gameServerId } = data;
  const { page, item, action } = args;
  const prefix = (await takaro.settings.settingsControllerGetOne('commandPrefix', gameServerId)).data.data.value;

  // If command is called without any arguments
  const messageWithoutPrefix = data.chatMessage.msg.slice(prefix.length).trim();
  if (!messageWithoutPrefix.includes(' ')) {
    await player.pm('This command allows you to browse the shop and view available items.');
    await player.pm(`Usage: ${prefix}shop [page] [item] [action]`);
    await player.pm(`${prefix}shop 2 - View the second page of shop items`);
    await player.pm(`${prefix}shop 1 3 - View details about the third item on the first page`);
    await player.pm(`${prefix}shop 1 3 buy - Purchase the third item on the first page`);
    return;
  }

  const shopItems = await takaro.shopListing.shopListingControllerSearch({
    limit: 5,
    page: page - 1,
    sortBy: 'name',
    sortDirection: 'asc',
    filters: {
      gameServerId: [gameServerId],
      draft: false,
    },
  });

  if (shopItems.data.data.length === 0) {
    await player.pm('No items found.');
    return;
  }

  const currencyName = (await takaro.settings.settingsControllerGetOne('currencyName', data.gameServerId)).data.data;

  if (!item) {
    // List the shop items with index
    let index = 1;
    for (const listing of shopItems.data.data) {
      const items = listing.items.slice(0, 3).map((item) => {
        return `${item.amount}x ${item.item.name}`;
      });
      // GH #2520 - a finite stock is shown so a player can see what is left before buying.
      const stockNote = listing.stock === null || listing.stock === undefined ? '' : ` (${listing.stock} left)`;
      await player.pm(
        `${index} - ${listing.name} - ${listing.price} ${currencyName.value}${stockNote}. ${items.join(', ')}`,
      );
      index++;
    }
    return;
  }

  const selectedItem = shopItems.data.data[item - 1];
  if (!selectedItem) {
    throw new TakaroUserError(
      `Item not found. Please select an item from the list, valid options are 1-${shopItems.data.data.length}.`,
    );
  }

  if (action === 'none') {
    // Display more info about the item
    await player.pm(`Listing ${selectedItem.name} - ${selectedItem.price} ${currencyName.value}`);
    if (selectedItem.requiredVariableKey) {
      const phrase = REQUIREMENT_PHRASES[selectedItem.requiredVariableOperator];
      await player.pm(
        `Requires ${selectedItem.requiredVariableKey} ${phrase} ${selectedItem.requiredVariableThreshold}.`,
      );
    }
    await Promise.all(
      selectedItem.items.map((item) => {
        const quality = item.quality ? `Quality: ${item.quality}` : '';
        const description = (item.item.description ? `Description: ${item.item.description}` : '').replaceAll(
          '\\n',
          ' ',
        );

        return player.pm(`- ${item.amount}x ${item.item.name}. ${quality} ${description}`);
      }),
    );
    return;
  }

  if (action === 'buy') {
    // Only a TakaroUserError reaches the player - anything else is shown as the generic
    // "Oops, something went wrong". A refusal (GH #2520, GH #2522) is always a 400 carrying the
    // reason, so translate that one status and let everything else rethrow: a 500's internals are
    // not game chat, and a bug should look like a bug.
    let orderRes;
    try {
      orderRes = await takaro.shopOrder.shopOrderControllerCreate({
        amount: 1,
        listingId: selectedItem.id,
        playerId: player.id,
      });
    } catch (error) {
      const apiMessage = error.response?.status === 400 ? error.response?.data?.meta?.error?.message : null;
      if (!apiMessage) {
        throw error;
      }
      throw new TakaroUserError(apiMessage);
    }

    // An instant listing comes back already COMPLETED; anything else still has to be claimed.
    // Only a COMPLETED order whose items were confirmed (or that had none) is a purchase to report.
    // The money is gone and the order stands either way, so buying again is never the advice.
    const pending = `Your purchase of ${selectedItem.name} went through, but it could not be handed over yet. Use /claim once you are in game to receive it.`;
    let order = orderRes.data.data;
    if (order.status === 'PAID') {
      try {
        order = (await takaro.shopOrder.shopOrderControllerClaim(order.id)).data.data;
      } catch {
        await player.pm(pending);
        return;
      }
    }

    if (order.status === 'COMPLETED' && order.deliveryStatus === 'UNKNOWN') {
      await player.pm(
        `Your purchase of ${selectedItem.name} went through, but Takaro could not confirm the items were handed over. Ask an admin to check it, and do not buy it again.`,
      );
      return;
    }
    if (
      order.status !== 'COMPLETED' ||
      (order.deliveryStatus !== 'DELIVERED' && order.deliveryStatus !== 'NOT_APPLICABLE')
    ) {
      await player.pm(pending);
      return;
    }

    await player.pm(`You have purchased ${selectedItem.name} for ${selectedItem.price} ${currencyName.value}.`);
    return;
  }

  throw new TakaroUserError('Invalid action. Valid actions are "buy".');
}

await main();

